type Statement struct {
	client       HttpServer
	ctx          context.Context
	baseUrl      string
	body         interface{}
	bodyResponse interface{}
	method       string
	baseHeader   []RequestHeader
}

func (r *Statement) WithContext(ctx context.Context) *Statement {
	r.ctx = ctx
	return r
}

func (r *Statement) Post(path string, args ...QueryKeyVal) *Statement {
	var url = r.baseUrl + path
	query := "?"
	for _, arg := range args {
		query += fmt.Sprintf("&%s=%s", arg.Key, arg.Val)
	}
	if len(args) > 0 {
		url += query
	}
	r.baseUrl = url
	r.method = http.MethodPost
	return r
}

func (r *Statement) BodyJSON(body interface{}) *Statement {
	r.baseHeader = append(r.baseHeader, RequestHeader{
		Key:   "Content-Type",
		Value: gin.MIMEJSON,
	})
	r.body = body
	return r
}

func (r *Statement) Send() error {
	if reflect.TypeOf(r.bodyResponse).Kind() != reflect.Pointer {
		return fmt.Errorf("body Response struct should be Pointer of struct")
	}

	if r.ctx == nil {
		r.ctx = context.Background()
	}

	request, err := r.client.CreateRequest(
		r.ctx,
		r.baseHeader,
		r.method,
		r.baseUrl,
		r.body,
	)
	if err != nil {
		return err
	}

	res, err := r.client.Do(request)
	if err != nil {
		return err
	}

	err = r.client.BindResponse(res, r.bodyResponse)
	if err != nil {
		return err
	}

	return nil
}

func (h HttpServer) convertToUrlFormData(data interface{}) (io.Reader, error) {
	forms := url.Values{}
	dType := reflect.TypeOf(data)
	dValue := reflect.ValueOf(data)

	if data == nil {
		return nil, nil
	}

	if dType.Kind() == reflect.Struct {
		for i := 0; i < dType.NumField(); i++ {
			key := dType.Field(i).Tag.Get("json")
			stval := dValue.Field(i)

			if str, ok := stval.Interface().(string); ok {
				forms.Set(key, str)
				continue
			}

			kind := dValue.Field(i).Kind()
			switch {
			case slices.Contains(TypeIsInt, kind):
				forms.Set(key, strconv.FormatInt(stval.Int(), 10))
				continue
			case slices.Contains(TypeIsUint, kind):
				forms.Set(key, strconv.FormatUint(stval.Uint(), 10))
				continue
			case slices.Contains(TypeIsFloat, kind):
				forms.Set(key, strconv.FormatFloat(stval.Float(), 'f', -1, 32))
				continue
			default:
				return nil, fmt.Errorf("invalid data type")
			}
		}

		p := strings.NewReader(forms.Encode())
		return p, nil
	}

	return nil, fmt.Errorf("only accept struct type")
}

func (d Engine) DeriveKey(password, salt []byte) ([]byte, []byte, error) {
	if salt == nil {
		salt = make([]byte, 32)
		if _, err := rand.Read(salt); err != nil {
			return nil, nil, err
		}
	}

	key, err := scrypt.Key(password, salt, 32768, 8, 1, 32)
	if err != nil {
		return nil, nil, err
	}

	return key, salt, nil
}

func (d Engine) EncryptMessage(key, data []byte) (string, error) {
	key, salt, err := d.DeriveKey(key, nil)
	if err != nil {
		return "", err
	}

	blockCipher, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}

	gcm, err := cipher.NewGCM(blockCipher)
	if err != nil {
		return "", err
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err = rand.Read(nonce); err != nil {
		return "", err
	}

	ciphertext := gcm.Seal(nonce, nonce, data, nil)
	ciphertext = append(ciphertext, salt...)

	return hex.EncodeToString(ciphertext), nil
}

func (d Engine) DecryptMessage(key []byte, p string) (string, error) {
	data, err := hex.DecodeString(p)
	if err != nil {
		return "", err
	}
	salt, data := data[len(data)-32:], data[:len(data)-32]

	key, _, err = d.DeriveKey(key, salt)
	if err != nil {
		return "", err
	}

	blockCipher, err := aes.NewCipher(key)
	if err != nil {
		return "", err
	}

	gcm, err := cipher.NewGCM(blockCipher)
	if err != nil {
		return "", err
	}

	nonce, ciphertext := data[:gcm.NonceSize()], data[gcm.NonceSize():]

	plaintext, err := gcm.Open(nil, nonce, ciphertext, nil)
	if err != nil {
		return "", err
	}

	return string(plaintext), nil
}

func (dc Engine) GenerateOTPCode(secret string, counter uint64) (int, error) {
	counterByte := make([]byte, 8)
	for i := 7; i >= 0; i-- {
		counterByte[i] = byte(counter & 0xff)
		counter >>= 8
	}

	secretByte, err := base32.StdEncoding.DecodeString(secret)
	if err != nil {
		return 0, fmt.Errorf("StdEncoding.DecodeString: %w", err)
	}
	hash := hmac.New(sha1.New, secretByte)
	_, err = hash.Write(counterByte)
	if err != nil {
		return 0, fmt.Errorf("hash.Write: %w", err)
	}
	hmacBytes := hash.Sum(nil)

	// Dynamic truncation in RFC 4226
	offset := hmacBytes[len(hmacBytes)-1] & 0xf
	code := (int(hmacBytes[offset])&0x7f)<<24 |
		(int(hmacBytes[offset+1])&0xff)<<16 |
		(int(hmacBytes[offset+2])&0xff)<<8 |
		(int(hmacBytes[offset+3]) & 0xff)
	code = code % 1000000

	f := fmt.Sprintf("%%0%dd", 6)
	codeStr := fmt.Sprintf(f, code)
	newCode, err := strconv.ParseInt(codeStr, 10, 64)
	if err != nil {
		return 0, fmt.Errorf("strconv.ParseInt newcode: %w", err)
	}

	return int(newCode), nil
}

