var (
	Search = func(val string, col ...string) clause.Expression {
		var exps = make([]clause.Expression, len(col))
		for i, c := range col {
			tableName, colName := getColNameStr(c)
			exps[i] = clause.Like{
				Column: clause.Column{Name: colName, Table: tableName},
				Value:  "%" + val + "%",
			}
		}
		return clause.Or(exps...)
	}

	Equal = func(val interface{}, col string) clause.Expression {
		tableName, colName := getColNameStr(col)
		return clause.Eq{
			Column: clause.Column{Name: colName, Table: tableName},
			Value:  val,
		}
	}
)

func (repo GenericRepository[T]) FindPagedByExpressionAndPreloadConditioned(
	ctx context.Context,
	cond []clause.Expression,
	paginate PaginationQuery,
	joins []string,
	preload []PreloadWithCondition,
	expType int,
) ([]T, int, error) {
	var result []T
	var total int64

	db := repo.db.WithContext(ctx).Model(&result)
	db = repo.applyWhereClause(cond, expType, db)

	for _, j := range joins {
		db = db.Joins(j)
	}

	for _, s := range preload {
		if len(s.Args) == 0 {
			db = db.Preload(s.ColName)
		} else {
			db = db.Preload(s.ColName, s.Args...)
		}
	}

	if errCount := db.Count(&total).Error; errCount != nil {
		return nil, 0, errCount
	}

	offset := paginate.PerPage * (paginate.Page - 1)
	err := db.Offset(offset).Limit(paginate.PerPage).Find(&result).Error
	return result, int(total), err
}

func (repo GenericRepository[T]) extractSelection(entity interface{}) ([]string, error) {
	typeOf := reflect.TypeOf(entity)
	if typeOf.Kind() != reflect.Ptr {
		return nil, fmt.Errorf("should had parsing entity struct pointer to parameter")
	}

	var results = make([]string, 0)
	elem := typeOf.Elem()
	switch elem.Kind() {
	case reflect.Struct:
		results = repo.fromStruct(elem)
	case reflect.Array, reflect.Slice:
		results = repo.fromStruct(elem.Elem())
	}
	return results, nil
}

func (repo GenericRepository[T]) fromStruct(elem reflect.Type) []string {
	var results = make([]string, elem.NumField())
	for i := 0; i < elem.NumField(); i++ {
		field := elem.Field(i)
		gormTag := field.Tag.Get("gorm")
		var columnName string
		if strings.Contains(gormTag, "column:") {
			parts := strings.Split(gormTag, ";")
			for _, part := range parts {
				part = strings.TrimSpace(part)
				if strings.HasPrefix(part, "column:") {
					columnName = strings.TrimPrefix(part, "column:")
					break
				}
			}
		}
		if columnName != "" {
			results[i] = columnName
		}
	}
	return results
}

type BaseRepository interface {
	SetupConnection(db *gorm.DB)
}

type DBTransaction struct {
	db    *gorm.DB
	repos []BaseRepository
}

func NewDBTransaction(db *gorm.DB, repos ...BaseRepository) DBTransaction {
	var result = DBTransaction{
		db:    db,
		repos: make([]BaseRepository, 0),
	}
	for _, repo := range repos {
		result.repos = append(result.repos, repo)
	}
	return result
}

func (main *DBTransaction) Begin() {
	begin := main.db.Begin()

	for _, rp := range main.repos {
		rp.SetupConnection(begin)
	}

	main.db = begin
}

func (main *DBTransaction) End(err error) error {
	if err != nil {
		errTrx := main.db.Rollback().Error
		if errTrx != nil {
			return errTrx
		}
		return nil
	}
	errTx := main.db.Commit().Error
	if errTx != nil {
		return errTx
	}
	return nil
}

func (main *DBTransaction) GetRepository(repo BaseRepository) BaseRepository {
	pTypeRepo := reflect.TypeOf(repo).Elem()

	for _, rp := range main.repos {
		pTypeMain := reflect.TypeOf(rp).Elem()
		if pTypeMain.Name() == pTypeRepo.Name() &&
			pTypeMain.PkgPath() == pTypeRepo.PkgPath() {
			return rp
		}
	}

	return repo
}

func (repo userRepo) UserDashboardList(ctx context.Context, query UserListQuery) ([]domain.UserListItem, int, int, error) {
